//go:build windows
package host
import("context";"os";"os/exec";"path/filepath";"strings";"testing";"runtime";"time";"researchos.local/research-os/internal/domain")
func reviewGit(t *testing.T, dir string, args ...string){ t.Helper(); c:=exec.Command("git",args...);c.Dir=dir;if out,err:=c.CombinedOutput();err!=nil{t.Fatalf("git %v: %v %s",args,err,out)}}
func reviewRepo(t *testing.T)(*Host,string){h,w,_:=runtimeToolFixture(t,AccessReadWrite);reviewGit(t,w,"init","-q");reviewGit(t,w,"config","user.email","test@example.invalid");reviewGit(t,w,"config","user.name","Review");return h,w}
func TestReviewDiffCleanFilterExecution(t *testing.T){h,w:=reviewRepo(t); os.WriteFile(filepath.Join(w,"tracked.txt"),[]byte("before\n"),0600);reviewGit(t,w,"add","tracked.txt");reviewGit(t,w,"commit","-qm","baseline");os.WriteFile(filepath.Join(w,".gitattributes"),[]byte("tracked.txt filter=review\n"),0600);reviewGit(t,w,"config","filter.review.clean","echo FILTER_EXECUTED > review-executed.txt; cat");os.WriteFile(filepath.Join(w,"tracked.txt"),[]byte("after\n"),0600);_,_,err:=h.WorkspaceDiff(context.Background(),w,AccessReadWrite,domain.Object{"workspace_ref":"opaque","base":"HEAD","relative_path":nil,"max_bytes":4096});b,e:=os.ReadFile(filepath.Join(w,"review-executed.txt"));if e==nil{t.Fatalf("unsafe repository filter executed during read-only diff: %q; diff err=%v",b,err)}}
func TestReviewDiffLiteralPathspec(t *testing.T){h,w:=reviewRepo(t);for _,n:=range []string{"a[1].txt","a1.txt"}{os.WriteFile(filepath.Join(w,n),[]byte("before\n"),0600)};reviewGit(t,w,"add",".");reviewGit(t,w,"commit","-qm","baseline");for _,n:=range []string{"a[1].txt","a1.txt"}{os.WriteFile(filepath.Join(w,n),[]byte("after\n"),0600)};r,b,e:=h.WorkspaceDiff(context.Background(),w,AccessReadWrite,domain.Object{"workspace_ref":"opaque","base":"HEAD","relative_path":"a[1].txt","max_bytes":4096});if e!=nil{t.Fatal(e)};if strings.Contains(string(b),"diff --git a/a1.txt"){t.Fatalf("literal path diff includes unrelated file: result=%v full=%s",r,b)}}
type reviewReadRaceContext struct {context.Context; mutate func(); done bool}
func (c *reviewReadRaceContext) Err()error {_,f,_,_:=runtime.Caller(1);if !c.done && strings.HasSuffix(f,"workspace_files_windows.go"){c.done=true;c.mutate()};return nil}
func TestReviewReadMetadataSameSizeRace(t *testing.T){h,w:=reviewRepo(t);p:=filepath.Join(w,"race.txt");os.WriteFile(p,[]byte("before\n"),0600);stamp:=time.Date(2030,1,1,0,0,0,0,time.UTC);ctx:=&reviewReadRaceContext{Context:context.Background(),mutate:func(){if e:=os.Rename(p,p+".old");e!=nil{t.Fatal(e)};os.WriteFile(p,[]byte("second\n"),0600);os.Chtimes(p,stamp,stamp)}};r,e:=h.WorkspaceRead(ctx,w,AccessReadWrite,domain.Object{"workspace_ref":"opaque","relative_path":"race.txt","max_bytes":4096});if e==nil && r["text"]=="before\n" && r["modified_at"]==stamp.Format(time.RFC3339Nano){t.Fatalf("old bytes paired with replacement metadata: %v",r)}}
func TestReviewDiffHashPatchRace(t *testing.T){h,w:=reviewRepo(t);p:=filepath.Join(w,"tracked.txt");os.WriteFile(p,[]byte("baseline\n"),0600);reviewGit(t,w,"add",".");reviewGit(t,w,"commit","-qm","baseline");os.WriteFile(p,[]byte("snapshot-A\n"),0600);ctx:=&reviewReadRaceContext{Context:context.Background(),mutate:func(){if e:=os.Rename(p,p+".old");e!=nil{t.Fatal(e)};os.WriteFile(p,[]byte("snapshot-B\n"),0600)}};r,b,e:=h.WorkspaceDiff(ctx,w,AccessReadWrite,domain.Object{"workspace_ref":"opaque","base":"HEAD","relative_path":"tracked.txt","max_bytes":4096});if e!=nil{t.Fatal(e)};entry:=r["files"].([]any)[0].(domain.Object);if entry["after_hash"]==domain.Digest([]byte("snapshot-A\n")) && strings.Contains(string(b),"+snapshot-B"){t.Fatalf("hash identifies A while patch publishes B: %v patch=%s",entry,b)}}